using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Threading.Tasks;using System.Security.Cryptography;using UnityEngine;using UnityEngine.UI;using HabitatIsland;
public static class Feedback221708FlowChecks
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;const string Dir="Verification/feedback-221708";static HabitatGame g;static StringBuilder log;static int count;
 static object Call(string n,params object[] a)=>typeof(HabitatGame).GetMethod(n,F).Invoke(g,a);
 static void Check(bool v,string s){log.AppendLine((v?"PASS ":"FAIL ")+s);File.WriteAllText(Dir+"/flow.txt",log.ToString());if(!v)throw new Exception(s+" "+g.State.message);count++;}
 static async Task Frames(int n=3){int end=Time.frameCount+n;while(Time.frameCount<end)await Task.Delay(12);}
 static async Task Until(Func<bool> f,string s,int limit=30){double end=Time.realtimeSinceStartupAsDouble+limit;while(!f()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("timeout "+s);await Frames(1);}}
 static string Hashes(string p){using(var sha=SHA256.Create())return !Directory.Exists(p)?"":string.Join("\n",Directory.GetFiles(p,"*",SearchOption.AllDirectories).OrderBy(x=>x).Select(x=>x+Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(x)))));}
 static async Task Shot(string s){await Frames(3);ScreenCapture.CaptureScreenshot(Path.GetFullPath(Dir+"/"+s+".png"));await Frames(8);}
 public static async Task<string> Run()
 {
  g=HabitatGame.Instance;log=new StringBuilder();var sf=typeof(HabitatGame).GetField("SaveSlotDirectoryForTests",BindingFlags.Static|BindingFlags.NonPublic);object old=sf.GetValue(null);string real=Path.Combine(Application.persistentDataPath,"Playtests"),hash=Hashes(real);sf.SetValue(null,Path.GetFullPath(Dir+"/isolated-flow-"+DateTime.Now.ToString("HHmmssfff")));object saved=Call("CaptureSnapshot");bool paused=g.paused,started=g.SessionStarted;int tool=g.tool;
  try
  {
   g.LoadLevel(5);g.paused=true;g.Hud.ClosePanels();typeof(HabitatGame).GetProperty("SessionStarted").SetValue(g,true);
   var s=g.State;s.width=7;s.depth=5;s.tiles=Enumerable.Range(0,35).Select(i=>new Tile{height=1}).ToArray();s.animals.Clear();s.playerX=s.dockX=3;s.playerZ=s.dockZ=1;s.onHarbor=false;s.rod=s.specialRod=s.chapterOneAccepted=s.chapterOneDelivered=true;s.chapterOneMorningSeen=false;s.coins=s.fish=0;s.waterLevel=0;s.won=false;s.tiles[16].height=0;
   s.animals.Add(new Animal{id=1,x=2,z=2,species=Species.Goldfish,offspring=2});s.animals.Add(new Animal{id=2,x=4,z=2,species=Species.Jellyfish});g.View.Initialize(s);await Frames(8);
   Check(HabitatRules.Fish(s,2,2,Species.Goldfish,g.tuning)&&HabitatRules.Fish(s,2,2,Species.Goldfish,g.tuning)&&s.fish==3,"partial-goal catch and existing offspring yield three sale fish");
   g.ReturnToHarbor();await Frames();Check(HabitatLevels.IsHomeHarbor(g.State)&&g.State.fish==3&&!g.HasCompletedLevel(5),"return before clear preserves catch and unfinished island");g.View.Harbor.TryPlaceAt(g.State,HabitatImportedDockLayout.ShopApproach);g.Hud.ClosePanels();Check(g.SellQuantity(Species.Goldfish,3)&&g.State.coins==300&&g.State.fish==0,"sell partial catch for real 300 coins");Check(g.BuyQuantity("shovel",1)&&g.State.coins==0&&g.State.shovels==1,"purchase tool with proceeds");
   Check(!g.CanTravelToLevel(6,out _),"hand-in/partial harvest does not unlock next island");g.View.Harbor.TryPlaceAt(g.State,HabitatImportedDockLayout.BoatApproach);g.Hud.ClosePanels();g.SailToLevel(5);Check(g.StoryPlaying,"revisit uses real departure sequence");await Frames(15);await Shot("departure-task-ui");var panel=(GameObject)typeof(HabitatHud).GetField("storyPanel",F).GetValue(g.Hud);Check(!panel.GetComponent<Image>()&&panel.GetComponentsInChildren<RawImage>().Any(r=>r.texture&&r.texture.name=="R20"),"legacy white cinematic card replaced by official task art");g.Story.Skip();await Frames(10);g.Hud.ClosePanels();Check(g.State.levelIndex==5&&!g.State.won&&g.State.shovels==1&&g.State.coins==0,"revisit keeps new tool and unfinished state");Check(g.State.tiles[16].height==0&&g.State.animals.Count==2&&g.State.animals[0].catchClaimed&&g.State.animals[0].offspring==0,"revisit preserves terrain, parents and harvested flags");Check(!HabitatRules.CanHarvest(g.State,g.State.animals[0],g.tuning,out _),"unfinished island revisit cannot duplicate first catch");
   g.State.firstClearCgSeen=true;Check(g.SaveSession(1),"new CG flag save");g.State.firstClearCgSeen=false;Check(g.LoadSession(1)&&g.State.firstClearCgSeen,"new CG flag load");Check(g.State.shovels==1&&!g.State.won,"save/load preserves trade and unfinished puzzle");g.Hud.ClosePanels();
   var shrimp=HabitatRules.Clone(s);shrimp.won=false;shrimp.animals.Add(new Animal{id=3,x=3,z=1,species=Species.Shrimp,carried=true});shrimp.backBasketUnlocked=true;shrimp.carryingAnimal=3;int total=shrimp.animals.Count;Check(HabitatRules.StoreCarriedShrimp(shrimp)&&shrimp.shrimp==1&&shrimp.animals.Count==total&&!shrimp.animals.Last().carried,"pre-clear shrimp harvest retains a resident parent");Check(!HabitatMechanicLevels.CompleteHabitat(shrimp,g.tuning),"harvesting shrimp cannot remove unfinished species from goals");
   g.LoadLevel(8);g.paused=true;g.Hud.ClosePanels();int calls=0;g.Story.BeginCg("cg00",()=>calls++);await Until(()=>g.Story.CgPlayer&&g.Story.CgPlayer.time>=2,"CG bright frame");await Shot("opening-cg00-mid");Check(g.Story.CgPlayer.width==1920&&g.Story.CgPlayer.height==1080,"original 1920x1080 CG aspect retained");g.LoadLevel(8);await Frames(6);Check(!g.StoryPlaying&&calls==0,"load level cancels CG without calling completion");
   g.Story.BeginCg("cg01",()=>calls++);await Until(()=>g.Story.CgPlayer&&g.Story.CgPlayer.time>=2,"CG 01 bright frame");await Shot("first-clear-cg01-mid");g.Story.Cancel();g.Story.BeginCg("cg03",()=>calls++);await Until(()=>g.Story.CgPlayer&&g.Story.CgPlayer.time>=2,"CG03 bright frame");await Shot("home-cg03-mid");g.Story.Cancel();
   return "PASS "+count+" flow checks; isolated partial-goal fixture, not full campaign.";
  }
  finally{g.Story.Cancel();Call("CancelPendingAction");if(g.Fishing)g.Fishing.Cancel(false);Call("RestoreSnapshot",saved);g.paused=paused;g.tool=tool;typeof(HabitatGame).GetProperty("SessionStarted").SetValue(g,started);g.Hud.ClosePanels();sf.SetValue(null,old);Check(Hashes(real)==hash,"real player save SHA256 unchanged");}
 }
}
